306	    /**
307	     * Fixed city-to-region table mapping each known city to its canonical region string.
308	     */
309	    private static final Map<String, String> CITY_REGION = Map.of(
310	        "Sydney", "NSW",
311	        "Melbourne", "VIC",
312	        "Brisbane", "QLD");
313	
314	    /**
315	     * Region -> inclusive {low, high} four-digit postcode range: the single canonical home of the
316	     * postcode bands (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), read via
317	     * {@link #postcodeRangeOf(String)} by both locality derivation and the create-time range check.
318	     */
319	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
320	        "NSW", new int[] {2000, 2099},
321	        "VIC", new int[] {3000, 3099},
322	        "QLD", new int[] {4000, 4099});
323	
324	    /**
325	     * The canonical region for {@code city} derived from the fixed city-to-region table
326	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the
327	     * city is not in the table. The single source of truth for the create-time postcode range check in
328	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerPostcode}.
329	     */
330	    public static String regionOf(String city) {
331	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
332	    }
333	
334	    /**
335	     * The inclusive {low, high} four-digit postcode band for {@code region} (NSW 2000-2099,
336	     * VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no band. This is the single
337	     * source of truth for the bands, shared by {@link #regionOfPostcode(String) the postcode-to-region
338	     * lookup} (which feeds the customerCode's region, and hence the locality) and the create-time
339	     * postcode range check.
340	     */
341	    public static int[] postcodeRangeOf(String region) {
342	        return REGION_POSTCODES.get(region);
343	    }
344	
345	    /**
346	     * The canonical region whose postcode band contains {@code postcode} (NSW 2000-2099, VIC 3000-3099,
347	     * QLD 4000-4099), or {@code null} when {@code postcode} is absent, not four digits, or in no known
348	     * range.
349	     */
350	    public static String regionOfPostcode(String postcode) {
351	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
352	            return null;
353	        }
354	        int value = Integer.parseInt(postcode);
355	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
356	            int[] range = entry.getValue();
357	            if (value >= range[0] && value <= range[1]) {
358	                return entry.getKey();
359	            }
360	        }
361	        return null;
362	    }
363	
364	    /**
365	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customerCode}, which is
366	     * the region code derived from the postcode at creation (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
367	     * else {@code "UNKNOWN"}). The customer code is the single region-and-hash owner identity, so the
368	     * locality reads straight off it rather than re-deriving the region. {@code "UNKNOWN"} when no
369	     * customer code is assigned.
370	     */
371	    public String getLocality() {
372	        if (this.customerCode == null) {
373	            return "UNKNOWN";
374	        }
375	        int dash = this.customerCode.indexOf('-');
376	        return dash > 0 ? this.customerCode.substring(0, dash) : "UNKNOWN";
377	    }
378	
379	    /**
380	     * The single Luhn check digit (0-9) computed over the digits contained in the
381	     * {@link #getCustomerCode() customerCode}: non-digit characters are ignored, each second digit from
382	     * the right is doubled (subtracting 9 when the double exceeds 9), the results are summed, and the
383	     * check digit is {@code (10 - sum % 10) % 10}. {@code 0} when no customer code is assigned.
384	     */
385	    public int getCheckDigit() {
386	        String code = this.customerCode;
387	        if (code == null) {
388	            return 0;
389	        }
390	        int sum = 0;
391	        boolean dbl = true;
392	        for (int i = code.length() - 1; i >= 0; i--) {
393	            char c = code.charAt(i);
394	            if (c < '0' || c > '9') {
395	                continue;
396	            }
397	            int d = c - '0';
398	            if (dbl) {
399	                d *= 2;
400	                if (d > 9) {
401	                    d -= 9;
402	                }
403	            }
404	            sum += d;
405	            dbl = !dbl;
406	        }
407	        return (10 - (sum % 10)) % 10;
408	    }
409	
410	    /**
411	     * The owner's preferred contact channel: {@code "EMAIL"} when an email is present, otherwise
412	     * {@code "PHONE"}.
413	     */
414	    public String getContactPreference() {
415	        boolean hasEmail = this.email != null && !this.email.isBlank();
416	        return hasEmail ? "EMAIL" : "PHONE";
417	    }
418	
419	    /**
420	     * The single canonical format of an owner's derived identity key:
421	     * {@code telephone + "|" + (email or empty) + "|" + (householdId or empty)}. The telephone and
422	     * household id are used as given (they are expected to already be canonical: E.164 and an assigned
423	     * household id); the email is lower-cased here and a null/blank email, telephone or household id
424	     * contributes an empty component. This is the only place the {@code "|"}-join lives; the stored-owner
425	     * {@link #getIdentityKey()} routes through here so the format cannot drift. The key is a descriptive,
426	     * returned field; create-time duplicate detection itself is keyed on the household alone (see
427	     * {@code CheckHouseholdUnique}).
428	     */
429	    public static String identityKey(String telephone, String email, String householdId) {
430	        String tel = (telephone == null) ? "" : telephone;
431	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
432	        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
433	        return tel + "|" + mail + "|" + household;
434	    }
435	
436	    /**
437	     * The owner's derived identity key, built from its stored canonical telephone (E.164), email and
438	     * household id via {@link #identityKey(String, String, String)}. A descriptive, returned value;
439	     * create-time duplicate detection is keyed on the household (see {@code CheckHouseholdUnique}).
440	     */
441	    public String getIdentityKey() {
442	        return identityKey(this.telephone, this.email, this.householdId);
443	    }
444	
445	    protected Set<Pet> getPetsInternal() {
446	        if (this.pets == null) {
447	            this.pets = new HashSet<>();
448	        }
449	        return this.pets;
450	    }
451	
452	    protected void setPetsInternal(Set<Pet> pets) {
453	        this.pets = pets;
454	    }
455	
456	    public List<Pet> getPets() {
457	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
458	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
459	        return Collections.unmodifiableList(sortedPets);
460	    }
461	
462	    public void setPets(List<Pet> pets) {
463	        this.pets = new HashSet<>(pets);
464	    }
465	
466	    public void addPet(Pet pet) {
467	        getPetsInternal().add(pet);
468	        pet.setOwner(this);
469	    }
470	
471	    /**
472	     * Return the Pet with the given name, or null if none found for this Owner.
473	     *
474	     * @param name to test
475	     * @return true if pet name is already in use
476	     */
477	    public Pet getPet(String name) {
478	        return getPet(name, false);
479	    }
480	
481	    /**
482	     * Return the Pet with the given name, or null if none found for this Owner.
483	     *
484	     * @param name to test
485	     * @return true if pet name is already in use
486	     */
487	    public Pet getPet(String name, boolean ignoreNew) {
488	        name = name.toLowerCase();
489	        for (Pet pet : getPetsInternal()) {
490	            if (!ignoreNew || !pet.isNew()) {
491	                String compName = pet.getName();
492	                compName = compName.toLowerCase();
493	                if (compName.equals(name)) {
494	                    return pet;
495	                }
496	            }
497	        }
498	        return null;
499	    }
500	
501	    public Pet getPet(Integer petId) {
502	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
503	    }
504	
505	    @Override
506	    public String toString() {
507	        return new ToStringCreator(this)
508	
509	            .append("id", this.getId())
510	            .append("new", this.isNew())
511	            .append("lastName", this.getLastName())
512	            .append("firstName", this.getFirstName())
513	            .append("address", this.address)
514	            .append("city", this.city)
515	            .append("telephone", this.telephone)
516	            .toString();
517	    }
518	}
